steps.text:
//--- VIOC tropical_gear: ropa de selva en mapas tropicales y armas 2035/WWII fuera de las listas de la IA
//--- (Common\Functions\VIOC_TropicalGear.sqf; parametro de lobby VIOC_TROPICAL_GEAR)
call compile preprocessFileLineNumbers "Common\Functions\VIOC_TropicalGear.sqf";

//--- VIOC tropical_gear: en mapas de selva tambien los PUEBLOS (y lo que se compra en el cuartel) con camuflaje de selva,
//--- no urbano (UCP gris, Ratnik otono, Flora de montana). Solo epoca moderna. Parametro de lobby VIOC_TROPICAL_GEAR.
if (isNil "VIOC_TG_WORLDS") then {VIOC_TG_WORLDS = ["tanoa", "cam_lao_nam", "vn_khe_sanh", "vn_the_bra"]};
if ((missionNamespace getVariable ["VIOC_TROPICAL_GEAR", 1]) isEqualTo 1 && {(toLower worldName) in VIOC_TG_WORLDS} && {!(CTI_GM_DLC > 1)} && {!(CTI_SOG_DLC > 1)}) then {CTI_CAMO_ACTIVATION = 3; CTI_TOWN_CAMO = 3};

class VIOC_TROPICAL_GEAR {
	title = "VIOC: Ropa de selva en mapas tropicales (pueblos con camuflaje de selva, guerrilla con ropa tropical, variedad por rol; la IA sin armas de 2035 ni de la 2a Guerra Mundial)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
